/*
 Problem: 3620. Network Recovery Pathways
 Language: cpp
 Runtime: 171 ms (87.24%)
 Memory: 301.7 MB (93.25%)
 Tags: Array, Binary Search, Dynamic Programming, Graph Theory, Topological Sort, Heap (Priority Queue), Shortest Path
*/
class Solution {
public:
    int findMaxPathScore(vector<vector<int>>& edges, vector<bool>& online, long long k) {
        int n = online.size();

        vector<vector<pair<int, int>>> adj(n);
        vector<int> indegree(n);

        int maxCost = 0;

        for (const auto& edge : edges) {
            adj[edge[0]].emplace_back(edge[1], edge[2]);
            ++indegree[edge[1]];
            maxCost = max(maxCost, edge[2]);
        }

        vector<int> topo;
        topo.reserve(n);

        queue<int> q;

        for (int i = 0; i < n; ++i) {
            if (!indegree[i]) {
                q.push(i);
            }
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            topo.emplace_back(u);

            for (const auto& edge : adj[u]) {
                const auto& [v, _] = edge;

                if (!--indegree[v]) {
                    q.push(v);
                }
            }
        }

        auto check = [&](int limit) {
            static constexpr long long INF = 1LL << 60;

            vector<long long> dp(n, INF);
            dp[0] = 0;

            for (const int u : topo) {
                if (dp[u] == INF) {
                    continue;
                }

                for (const auto& edge : adj[u]) {
                    const auto& [v, cost] = edge;

                    if (cost < limit) {
                        continue;
                    }

                    if (v != n - 1 && !online[v]) {
                        continue;
                    }

                    dp[v] = min(dp[v], dp[u] + cost);
                }
            }

            return dp.back() <= k;
        };

        if (!check(0)) {
            return -1;
        }

        int left = 0;
        int right = maxCost;
        int ans = 0;

        while (left <= right) {
            const int mid = left + ((right - left) >> 1);

            if (check(mid)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    }
};
